-- GOV-TAIL-2 (2026-11-05, charter pillar autonomy; slice B-governance-tail of the issue-backlog cluster). Follows GOV-TAIL-1 (PR 7331).
-- 1. BLINDSPOT-1 issues had no closing path: the hourly audit (fleet_tasks blind-spot-audit) files them with a stated closing condition ("Closes when this count is 0", "Closes when the
--    latest remediation_verifications row for the class passes") and its birth contract is the circular status-observing template, which the closing guard supersedes at birth (14 issues,
--    7 of them orphans with no live path). The audit now ends with a step `arm-closing-probes` that gives every open BLINDSPOT-1 issue the probe that measures exactly the condition its text
--    states (marker BLINDSPOT-ARMED-1, applied once per issue), and this file runs the same statement once for the issues open now. The hourly consumer then closes each issue by the normal
--    autoclose rule when its condition holds, and re-files nothing the audit does not re-find.
-- 2. The audit's migration-unapplied query counted a superseded run as failed, and a file whose newest run is superseded as never applied: three files (2026-11-02-management-personas-metric-intake,
--    2026-10-13-fleet-journeys, 2026-10-18-issue-sla-window-retry) have an earlier ok run or an applied twin and were already marked superseded by migration_runs 1263, 1264 and 333. The audit query
--    (step migration-unapplied) and the probe armed below now treat a later superseded run like a later ok run, so the count reads only a file that really never applied (live: 0).
-- 3. Three beliefs of the form alt-unexercisable-<control> were contradicted because the record that makes the alternate readable now exists (model_floor_guard_runs, written by the
--    model-floor-guard workflow; a cloud_ops_events ai-skip row on 2026-11-02 shows the wait path ran). Each control gets its control_alternate_probes row, and the belief watcher goes quiet once
--    that row exists.
-- 4. Owner-bound cards (OWNER-HANDBACK 1001747, 1001749, 1001750, 1001751, 1001752) and issue 100384 had a superseded or unsatisfiable probe, so they counted as orphans with no live path. Each
--    now carries a d1-query probe in the deferral shape (a `pending:` read stamps deferred, writes no verification row and neither closes nor reopens anything) that turns ok the moment the owner
--    step is observable: a human_actions card resolved with a real resolution, or ai_spend_owner_client rows. Nothing here creates an account or touches an owner account.
-- APPLY-BY: ci
-- DB: qnfo-audit

-- Rollback: UPDATE remediation_contracts SET verify_probe=(SELECT b.verify_probe FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), verify_transport=(SELECT b.verify_transport FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), status=(SELECT b.status FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), last_verdict=(SELECT b.last_verdict FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), next_due_at=(SELECT b.next_due_at FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), attempts=(SELECT b.attempts FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class), module=(SELECT b.module FROM bak_20261105_gov_tail2_contracts b WHERE b.class=remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261105_gov_tail2_contracts); UPDATE fleet_tasks SET definition=(SELECT b.definition FROM bak_20261105_gov_tail2_task b WHERE b.id=fleet_tasks.id), updated_at=(SELECT b.updated_at FROM bak_20261105_gov_tail2_task b WHERE b.id=fleet_tasks.id) WHERE id IN (SELECT id FROM bak_20261105_gov_tail2_task); DELETE FROM control_alternate_probes WHERE window_note LIKE 'GOV-TAIL-2:%';
-- The Rollback leaves the decision_log row: decision_log is append-only.

CREATE TABLE IF NOT EXISTS bak_20261105_gov_tail2_contracts AS
SELECT class, issue_id, verify_probe, verify_transport, status, last_verdict, next_due_at, attempts, module
FROM remediation_contracts
WHERE class IN ('issue-1001747', 'issue-1001749', 'issue-1001750', 'issue-1001751', 'issue-1001752', 'issue-100384', 'belief-alt-unexercisable-model_floor_pr_check', 'belief-alt-unexercisable-research-model-skip-gauge', 'belief-alt-unexercisable-research-fallback-price-guard')
   OR class IN (SELECT 'issue-' || id FROM agent_issues WHERE status = 'open' AND instr(title, 'BLINDSPOT-1: ') = 1);

CREATE TABLE IF NOT EXISTS bak_20261105_gov_tail2_task AS
SELECT id, definition, updated_at FROM fleet_tasks WHERE id = 'blind-spot-audit';

-- 1. every open BLINDSPOT-1 issue gets the probe that measures its stated closing condition
UPDATE remediation_contracts SET verify_probe = COALESCE((SELECT CASE WHEN instr(a.title, 'BLINDSPOT-1: belief ') = 1 AND instr(a.title, ' is contradicted by its live probe') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN COALESCE((SELECT v.pass FROM remediation_verifications v WHERE v.class = (SELECT b.probe_class FROM belief_registry b WHERE b.belief_key = ' || quote(substr(a.title, 21, instr(substr(a.title, 21), ' ') - 1)) || ') ORDER BY v.id DESC LIMIT 1), 0) = 1 THEN ''ok'' ELSE ''the latest probe of belief ' || substr(a.title, 21, instr(substr(a.title, 21), ' ') - 1) || ' still fails or has no reading'' END AS observed' WHEN instr(a.title, 'BLINDSPOT-1: belief ') = 1 AND instr(a.title, ' has no probe result in 48 hours') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN COALESCE((SELECT MAX(v.verified_at) FROM remediation_verifications v WHERE v.class = (SELECT b.probe_class FROM belief_registry b WHERE b.belief_key = ' || quote(substr(a.title, 21, instr(substr(a.title, 21), ' ') - 1)) || ')), '''') >= datetime(''now'', ''-48 hours'') THEN ''ok'' ELSE ''no reading of the probe of belief ' || substr(a.title, 21, instr(substr(a.title, 21), ' ') - 1) || ' in 48 hours'' END AS observed' WHEN instr(a.title, ' failure modes have a detector that never ran') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM failure_modes f WHERE f.probe_class IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = f.probe_class) OR NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = f.probe_class AND c.status = ''active''))) = 0 THEN ''ok'' ELSE (SELECT COUNT(*) FROM failure_modes f WHERE f.probe_class IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = f.probe_class) OR NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = f.probe_class AND c.status = ''active''))) || '' failure modes have a detector that never ran'' END AS observed' WHEN instr(a.title, ' metrics have not refreshed in 3 days') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE COALESCE(state, '''') <> ''RETIRED'' AND (last_refreshed IS NULL OR last_refreshed < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days''))) = 0 THEN ''ok'' ELSE (SELECT COUNT(*) FROM metric_registry WHERE COALESCE(state, '''') <> ''RETIRED'' AND (last_refreshed IS NULL OR last_refreshed < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days''))) || '' metrics have not refreshed in 3 days, for example '' || (SELECT MIN(metric) FROM metric_registry WHERE COALESCE(state, '''') <> ''RETIRED'' AND (last_refreshed IS NULL OR last_refreshed < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days''))) END AS observed' WHEN instr(a.title, ' merged code tasks have no deploy evidence after 2 hours') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM code_tasks WHERE merged_at > datetime(''now'', ''-7 days'') AND merged_at < datetime(''now'', ''-2 hours'') AND deployed_at IS NULL) = 0 THEN ''ok'' ELSE (SELECT COUNT(*) FROM code_tasks WHERE merged_at > datetime(''now'', ''-7 days'') AND merged_at < datetime(''now'', ''-2 hours'') AND deployed_at IS NULL) || '' merged code tasks have no deploy evidence after 2 hours'' END AS observed' WHEN instr(a.title, ' migration files have no ok row in migration_runs') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM migration_runs r WHERE status NOT IN (''ok'', ''superseded'') AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND (o.status = ''ok'' OR o.status = ''superseded'') AND o.id > r.id)) = 0 THEN ''ok'' ELSE (SELECT COUNT(*) FROM migration_runs r WHERE status NOT IN (''ok'', ''superseded'') AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND (o.status = ''ok'' OR o.status = ''superseded'') AND o.id > r.id)) || '' migration files have a failed run and no later ok run'' END AS observed' WHEN instr(a.title, ' active contracts are parked past their cadence') > 0 THEN 'SELECT ''ok'' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM remediation_contracts WHERE status = ''active'' AND next_due_at > datetime(''now'', ''+'' || (COALESCE(expected_cadence_h, 1) + 3) || '' hours'') AND class NOT LIKE ''goal-%'') = 0 THEN ''ok'' ELSE (SELECT COUNT(*) FROM remediation_contracts WHERE status = ''active'' AND next_due_at > datetime(''now'', ''+'' || (COALESCE(expected_cadence_h, 1) + 3) || '' hours'') AND class NOT LIKE ''goal-%'') || '' active contracts are parked past their cadence'' END AS observed' END FROM agent_issues a WHERE 'issue-' || a.id = remediation_contracts.class), verify_probe), verify_transport = 'd1-query', status = 'active', last_verdict = NULL, attempts = 0, next_due_at = datetime('now'), expected_cadence_h = 1, max_attempts = 3, module = 'blindspot-armed-1' WHERE class IN (SELECT 'issue-' || a.id FROM agent_issues a WHERE a.status = 'open' AND instr(a.title, 'BLINDSPOT-1: ') = 1 AND ((instr(a.title, 'BLINDSPOT-1: belief ') = 1 AND (instr(a.title, ' is contradicted by its live probe') > 0 OR instr(a.title, ' has no probe result in 48 hours') > 0)) OR instr(a.title, ' failure modes have a detector that never ran') > 0 OR instr(a.title, ' metrics have not refreshed in 3 days') > 0 OR instr(a.title, ' merged code tasks have no deploy evidence after 2 hours') > 0 OR instr(a.title, ' migration files have no ok row in migration_runs') > 0 OR instr(a.title, ' active contracts are parked past their cadence') > 0)) AND instr(COALESCE(verify_probe, ''), 'BLINDSPOT-ARMED-1') = 0;

-- the audit arms future issues itself, once per hour
UPDATE fleet_tasks SET definition = json_set(definition, '$.steps[' || json_array_length(definition, '$.steps') || ']', json_object('type', 'sql', 'name', 'arm-closing-probes', 'db', 'AUDIT', 'sql', 'UPDATE remediation_contracts SET verify_probe = COALESCE((SELECT CASE WHEN instr(a.title, ''BLINDSPOT-1: belief '') = 1 AND instr(a.title, '' is contradicted by its live probe'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN COALESCE((SELECT v.pass FROM remediation_verifications v WHERE v.class = (SELECT b.probe_class FROM belief_registry b WHERE b.belief_key = '' || quote(substr(a.title, 21, instr(substr(a.title, 21), '' '') - 1)) || '') ORDER BY v.id DESC LIMIT 1), 0) = 1 THEN ''''ok'''' ELSE ''''the latest probe of belief '' || substr(a.title, 21, instr(substr(a.title, 21), '' '') - 1) || '' still fails or has no reading'''' END AS observed'' WHEN instr(a.title, ''BLINDSPOT-1: belief '') = 1 AND instr(a.title, '' has no probe result in 48 hours'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN COALESCE((SELECT MAX(v.verified_at) FROM remediation_verifications v WHERE v.class = (SELECT b.probe_class FROM belief_registry b WHERE b.belief_key = '' || quote(substr(a.title, 21, instr(substr(a.title, 21), '' '') - 1)) || '')), '''''''') >= datetime(''''now'''', ''''-48 hours'''') THEN ''''ok'''' ELSE ''''no reading of the probe of belief '' || substr(a.title, 21, instr(substr(a.title, 21), '' '') - 1) || '' in 48 hours'''' END AS observed'' WHEN instr(a.title, '' failure modes have a detector that never ran'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM failure_modes f WHERE f.probe_class IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = f.probe_class) OR NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = f.probe_class AND c.status = ''''active''''))) = 0 THEN ''''ok'''' ELSE (SELECT COUNT(*) FROM failure_modes f WHERE f.probe_class IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = f.probe_class) OR NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = f.probe_class AND c.status = ''''active''''))) || '''' failure modes have a detector that never ran'''' END AS observed'' WHEN instr(a.title, '' metrics have not refreshed in 3 days'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE COALESCE(state, '''''''') <> ''''RETIRED'''' AND (last_refreshed IS NULL OR last_refreshed < strftime(''''%Y-%m-%dT%H:%M:%SZ'''', ''''now'''', ''''-3 days''''))) = 0 THEN ''''ok'''' ELSE (SELECT COUNT(*) FROM metric_registry WHERE COALESCE(state, '''''''') <> ''''RETIRED'''' AND (last_refreshed IS NULL OR last_refreshed < strftime(''''%Y-%m-%dT%H:%M:%SZ'''', ''''now'''', ''''-3 days''''))) || '''' metrics have not refreshed in 3 days, for example '''' || (SELECT MIN(metric) FROM metric_registry WHERE COALESCE(state, '''''''') <> ''''RETIRED'''' AND (last_refreshed IS NULL OR last_refreshed < strftime(''''%Y-%m-%dT%H:%M:%SZ'''', ''''now'''', ''''-3 days''''))) END AS observed'' WHEN instr(a.title, '' merged code tasks have no deploy evidence after 2 hours'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM code_tasks WHERE merged_at > datetime(''''now'''', ''''-7 days'''') AND merged_at < datetime(''''now'''', ''''-2 hours'''') AND deployed_at IS NULL) = 0 THEN ''''ok'''' ELSE (SELECT COUNT(*) FROM code_tasks WHERE merged_at > datetime(''''now'''', ''''-7 days'''') AND merged_at < datetime(''''now'''', ''''-2 hours'''') AND deployed_at IS NULL) || '''' merged code tasks have no deploy evidence after 2 hours'''' END AS observed'' WHEN instr(a.title, '' migration files have no ok row in migration_runs'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM migration_runs r WHERE status NOT IN (''''ok'''', ''''superseded'''') AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND (o.status = ''''ok'''' OR o.status = ''''superseded'''') AND o.id > r.id)) = 0 THEN ''''ok'''' ELSE (SELECT COUNT(*) FROM migration_runs r WHERE status NOT IN (''''ok'''', ''''superseded'''') AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND (o.status = ''''ok'''' OR o.status = ''''superseded'''') AND o.id > r.id)) || '''' migration files have a failed run and no later ok run'''' END AS observed'' WHEN instr(a.title, '' active contracts are parked past their cadence'') > 0 THEN ''SELECT ''''ok'''' AS expected /* BLINDSPOT-ARMED-1 */, CASE WHEN (SELECT COUNT(*) FROM remediation_contracts WHERE status = ''''active'''' AND next_due_at > datetime(''''now'''', ''''+'''' || (COALESCE(expected_cadence_h, 1) + 3) || '''' hours'''') AND class NOT LIKE ''''goal-%'''') = 0 THEN ''''ok'''' ELSE (SELECT COUNT(*) FROM remediation_contracts WHERE status = ''''active'''' AND next_due_at > datetime(''''now'''', ''''+'''' || (COALESCE(expected_cadence_h, 1) + 3) || '''' hours'''') AND class NOT LIKE ''''goal-%'''') || '''' active contracts are parked past their cadence'''' END AS observed'' END FROM agent_issues a WHERE ''issue-'' || a.id = remediation_contracts.class), verify_probe), verify_transport = ''d1-query'', status = ''active'', last_verdict = NULL, attempts = 0, next_due_at = datetime(''now''), expected_cadence_h = 1, max_attempts = 3, module = ''blindspot-armed-1'' WHERE class IN (SELECT ''issue-'' || a.id FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BLINDSPOT-1: '') = 1 AND ((instr(a.title, ''BLINDSPOT-1: belief '') = 1 AND (instr(a.title, '' is contradicted by its live probe'') > 0 OR instr(a.title, '' has no probe result in 48 hours'') > 0)) OR instr(a.title, '' failure modes have a detector that never ran'') > 0 OR instr(a.title, '' metrics have not refreshed in 3 days'') > 0 OR instr(a.title, '' merged code tasks have no deploy evidence after 2 hours'') > 0 OR instr(a.title, '' migration files have no ok row in migration_runs'') > 0 OR instr(a.title, '' active contracts are parked past their cadence'') > 0)) AND instr(COALESCE(verify_probe, ''''), ''BLINDSPOT-ARMED-1'') = 0')), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 'blind-spot-audit' AND json_valid(definition) = 1 AND instr(definition, 'arm-closing-probes') = 0;

-- 2. the audit counts a failed run only when no later run is ok or superseded (migration_runs 1263, 1264 and 333 are the superseding rows)

UPDATE fleet_tasks SET definition = replace(definition, 'FROM migration_runs r WHERE status <> ''ok'' AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND o.status = ''ok'' AND o.id > r.id)', 'FROM migration_runs r WHERE status NOT IN (''ok'', ''superseded'') AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND (o.status = ''ok'' OR o.status = ''superseded'') AND o.id > r.id)'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 'blind-spot-audit' AND instr(definition, 'FROM migration_runs r WHERE status <> ''ok'' AND NOT EXISTS') > 0;

-- 3. the alternates are readable now
INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('model_floor_pr_check', 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM model_floor_guard_runs WHERE instr(workflow_path, ''model-floor-guard.yml'') > 0 AND branch = ''main'' AND event IN (''push'', ''schedule'') AND run_started_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-12 hours'')) THEN ''no post-merge push or schedule run of the model-floor-guard workflow was recorded on main in 12 hours'' WHEN (SELECT conclusion FROM model_floor_guard_runs WHERE instr(workflow_path, ''model-floor-guard.yml'') > 0 AND branch = ''main'' AND event IN (''push'', ''schedule'') ORDER BY run_started_at DESC LIMIT 1) <> ''success'' THEN ''the newest model-floor-guard run on main did not succeed'' ELSE ''ok'' END AS observed', 'GOV-TAIL-2: 12 hours; the post-merge push run of .github/workflows/model-floor-guard.yml is recorded in model_floor_guard_runs (run_id, branch, event, conclusion, run_started_at) and pushes to main land every few minutes. The replay of the added, inherited, moved and removed cases stays in scripts/model-floor-guard.test.mjs', 1),
 ('research-model-skip-gauge', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cloud_ops_events s WHERE s.kind = ''ai-skip'' AND s.ts > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-14 days'') AND NOT EXISTS (SELECT 1 FROM cloud_ops_events d WHERE d.job = ''qnfo-research-exec'' AND d.kind = ''done'' AND d.status = ''ok'' AND d.ts > s.ts AND d.ts < strftime(''%Y-%m-%dT%H:%M:%fZ'', s.ts, ''+15 minutes''))) > 0 THEN ''a rate-limit wait (ai-skip) in the last 14 days was not followed by a finished research stage within 15 minutes'' ELSE ''ok'' END AS observed', 'GOV-TAIL-2: 14 days (the done event kind exists from 2026-10-27); event-driven. A rate-limit wait leaves a cloud_ops_events ai-skip row (the first on 2026-11-02T14); every such wait in the window must be followed by a finished research stage within 15 minutes. No wait in the window reads ok because there is nothing to retry; the gauge logic is pinned by qnfo-research-exec/width-governor.test.mjs', 1),
 ('research-fallback-price-guard', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cloud_ops_events s WHERE s.kind = ''ai-skip'' AND instr(s.text, ''no fallback at or under its price'') > 0 AND s.ts > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-14 days'') AND NOT EXISTS (SELECT 1 FROM cloud_ops_events d WHERE d.job = ''qnfo-research-exec'' AND d.kind = ''done'' AND d.status = ''ok'' AND d.ts > s.ts AND d.ts < strftime(''%Y-%m-%dT%H:%M:%fZ'', s.ts, ''+15 minutes''))) > 0 THEN ''a rate-limit wait (ai-skip) in the last 14 days was not followed by a finished research stage within 15 minutes'' ELSE ''ok'' END AS observed', 'GOV-TAIL-2: 14 days (the done event kind exists from 2026-10-27); event-driven. The wait path of the price guard leaves an ai-skip row whose text says no fallback at or under its price (2026-11-02T14); every one in the window must be followed by a finished research stage within 15 minutes. The rule itself is pinned by qnfo-research-exec/width-governor.test.mjs', 1);

UPDATE remediation_contracts SET verify_probe = replace(verify_probe, 'WHEN EXISTS (', 'WHEN NOT EXISTS (SELECT 1 FROM control_alternate_probes WHERE control = ''model_floor_pr_check'') AND EXISTS ('), last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'belief-alt-unexercisable-model_floor_pr_check' AND instr(verify_probe, 'FROM control_alternate_probes WHERE control = ') = 0;

UPDATE remediation_contracts SET verify_probe = replace(verify_probe, 'WHEN EXISTS (', 'WHEN NOT EXISTS (SELECT 1 FROM control_alternate_probes WHERE control = ''research-model-skip-gauge'') AND EXISTS ('), last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'belief-alt-unexercisable-research-model-skip-gauge' AND instr(verify_probe, 'FROM control_alternate_probes WHERE control = ') = 0;

UPDATE remediation_contracts SET verify_probe = replace(verify_probe, 'WHEN EXISTS (', 'WHEN NOT EXISTS (SELECT 1 FROM control_alternate_probes WHERE control = ''research-fallback-price-guard'') AND EXISTS ('), last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'belief-alt-unexercisable-research-fallback-price-guard' AND instr(verify_probe, 'FROM control_alternate_probes WHERE control = ') = 0;

-- 4. owner-bound items: a live, deferral-shaped closing probe instead of a superseded or unsatisfiable one

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM human_actions WHERE slug = ''ga4-internal-traffic-1'' AND status IN (''done'', ''resolved'') AND instr(COALESCE(resolution, ''''), ''handed back'') = 0) THEN ''ok'' ELSE ''pending: IDENTITY-BOUND owner step. In GA4 Admin, define internal traffic for the owner addresses and set the Internal Traffic data filter to Active (the property belongs to the owner Google account). The card is resolved only as a handback so far.'' END AS observed', verify_transport = 'd1-query', status = 'active', last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'issue-1001747' AND issue_id = 1001747 AND instr(COALESCE(verify_probe, ''), 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM hum') = 0;

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM human_actions WHERE slug = ''jobsearch-ledger-owner-answers'' AND status IN (''done'', ''resolved'') AND instr(COALESCE(resolution, ''''), ''handed back'') = 0) THEN ''ok'' ELSE ''pending: IDENTITY-BOUND owner step. Only the owner can state the US work-authorization basis and the NL permit type for the job search ledger (personal data, never guessed). The card is resolved only as a handback so far.'' END AS observed', verify_transport = 'd1-query', status = 'active', last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'issue-1001749' AND issue_id = 1001749 AND instr(COALESCE(verify_probe, ''), 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM hum') = 0;

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM human_actions WHERE slug = ''yt-channel-branding'' AND status IN (''done'', ''resolved'') AND instr(COALESCE(resolution, ''''), ''handed back'') = 0) THEN ''ok'' ELSE ''pending: IDENTITY-BOUND owner step. The channel name, description and banner are the owner own public identity: the owner supplies the wording or says keep as is. The card is resolved only as a handback so far.'' END AS observed', verify_transport = 'd1-query', status = 'active', last_verdict = NULL, attempts = 0, next_due_at = datetime('now') WHERE class = 'issue-1001750' AND issue_id = 1001750 AND instr(COALESCE(verify_probe, ''), 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM hum') = 0;

